/**
 * 极简 MD5（RFC 1321），只为 RandomSupport.seedFromHashOf 服务：
 * 原版用 Guava 的 Hashing.md5() 把 "minecraft:continentalness" 这类 ID
 * 哈希成 128 位，再拆成两个 long 作为 Xoroshiro 的种子。
 * 浏览器里 crypto.subtle 只有异步接口且不支持 MD5，所以自己实现。
 */

const S = [
  7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5,
  9, 14, 20, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 6, 10, 15, 21, 6, 10, 15, 21, 6,
  10, 15, 21, 6, 10, 15, 21
]

const K = new Int32Array(64)
for (let i = 0; i < 64; i++) {
  K[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 2 ** 32) | 0
}

export function md5(input: Uint8Array): Uint8Array {
  const len = input.length
  const paddedLen = (((len + 8) >> 6) + 1) << 6
  const buf = new Uint8Array(paddedLen)
  buf.set(input)
  buf[len] = 0x80
  const view = new DataView(buf.buffer)
  // 消息长度（比特）以小端 64 位写在末尾
  view.setUint32(paddedLen - 8, (len * 8) >>> 0, true)
  view.setUint32(paddedLen - 4, Math.floor((len * 8) / 2 ** 32), true)

  let a0 = 0x67452301
  let b0 = 0xefcdab89 | 0
  let c0 = 0x98badcfe | 0
  let d0 = 0x10325476

  const M = new Int32Array(16)
  for (let off = 0; off < paddedLen; off += 64) {
    for (let i = 0; i < 16; i++) M[i] = view.getInt32(off + i * 4, true)
    let a = a0
    let b = b0
    let c = c0
    let d = d0
    for (let i = 0; i < 64; i++) {
      let f: number
      let g: number
      if (i < 16) {
        f = (b & c) | (~b & d)
        g = i
      } else if (i < 32) {
        f = (d & b) | (~d & c)
        g = (5 * i + 1) & 15
      } else if (i < 48) {
        f = b ^ c ^ d
        g = (3 * i + 5) & 15
      } else {
        f = c ^ (b | ~d)
        g = (7 * i) & 15
      }
      const tmp = d
      d = c
      c = b
      const x = (a + f + K[i] + M[g]) | 0
      b = (b + ((x << S[i]) | (x >>> (32 - S[i])))) | 0
      a = tmp
    }
    a0 = (a0 + a) | 0
    b0 = (b0 + b) | 0
    c0 = (c0 + c) | 0
    d0 = (d0 + d) | 0
  }

  const out = new Uint8Array(16)
  const ov = new DataView(out.buffer)
  ov.setInt32(0, a0, true)
  ov.setInt32(4, b0, true)
  ov.setInt32(8, c0, true)
  ov.setInt32(12, d0, true)
  return out
}

const encoder = new TextEncoder()

export function md5String(s: string): Uint8Array {
  return md5(encoder.encode(s))
}
